// Fractal Noise - aggancio COLORI agli slider del dock (u_col1 / u_col2).
// Ricostruisce lo STESSO frattale usato nel displacement (stessi fattori
// costanti 2/4/8/16 e stesso scorrimento t*0.5), cosi' il colore segue il
// rilievo: u_col2 nelle valli, u_col1 sulle creste.
// Gira DENTRO shadeSurface() -> niente funzioni, tutto inline. 't' e 'sys_noise'
// sono disponibili (t = orologio texture; sys_noise vive in common.glsl).
// NB: fattori COSTANTI e non NoiseW(), per non far faultare l'Adreno (vedi displacement).

float n1 = sys_noise(pModel * 2.0  + vec3(0.0, t * 0.5, 0.0));
float n2 = sys_noise(pModel * 4.0  + vec3(0.0, t * 0.5, 0.0));
float n3 = sys_noise(pModel * 8.0  + vec3(0.0, t * 0.5, 0.0));
float n4 = sys_noise(pModel * 16.0 + vec3(0.0, t * 0.5, 0.0));
float fractal = (n1 + n2 * 0.5 + n3 * 0.25 + n4 * 0.125) / 1.875;

// contrasto: creste piu' nette
float tcol = smoothstep(0.35, 0.75, fractal);

// COLORI DEL DOCK: u_col2 = valli, u_col1 = creste
textureCol = mix(ubuf.u_col2, ubuf.u_col1, tcol);

